package com.booksyde.service; import com.booksyde.dto.request.SaveReadingProgressRequest; import com.booksyde.dto.response.*; import com.booksyde.entity.*; import com.booksyde.repository.*; import java.time.OffsetDateTime; import java.util.*; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class ReadingProgressService { private final ReadingProgressRepository repo; public ReadingProgressService(ReadingProgressRepository r){repo=r;} @Transactional(readOnly=true) public ReadingProgressResponse get(Jwt jwt,UUID volume){return repo.findByUserIdAndVolumeId(UUID.fromString(jwt.getSubject()),volume).map(this::map).orElse(new ReadingProgressResponse(volume,0,null,null));} @Transactional public ReadingProgressResponse save(Jwt jwt,UUID volume,SaveReadingProgressRequest req){UUID u=UUID.fromString(jwt.getSubject()); var e=repo.findByUserIdAndVolumeId(u,volume).orElseGet(()->new ReadingProgressEntity(u,volume,req.pageIndex(),req.completed()?OffsetDateTime.now():null)); e.update(req.pageIndex(),req.completed()?OffsetDateTime.now():e.getCompletedAt()); return map(repo.save(e));} private ReadingProgressResponse map(ReadingProgressEntity e){return new ReadingProgressResponse(e.getVolumeId(),e.getPageIndex(),e.getCompletedAt(),e.getUpdatedAt());}}